  Miktar: $input.first().json.body.miktar || "",
  mesaj: $input.first().json.body.mesaj || "",
  Tarih: tarih,
  Saat: saat,
  SiparisNo: siparisNo
};

return [
  {
    json: cleaned
  }
];

