// Tek satır veriyi al
const line = $json.tekSatir || "";

// Boşluklara göre ayır
const parts = line.trim().split(/\s+/);

// Parçaları alana yerleştir
const result = {
  Musteri: parts[0] || "",
  Telefon: (parts[1] + " " + parts[2] + " " + parts[3] + " " + parts[4]) || "",
  Email: parts[5] || "",
  Urun: parts[6] || "",
  Miktar: parts[7] || "",
  mesaj: parts.slice(8).join(" ") || ""   // geri kalanlar mesaj
};

return [
  {
    json: result
  }
];
